# Pictures for the elf library (read with ast.literal_eval; never run).
# The examples run through TB on two tiny demo files written from the hex
# below: demo (a 64-bit Linux program with a writable+executable segment)
# and libdemo.so (a shared object exporting two functions). They are made
# by tests/binfixtures.py and contain no real code.
SPEC = {
    "_default": {"imports": ["binary", "fs"], "setup": 'let bin = binary.from_hex("")\nfs.write_bytes("demo", bin)\nfs.write_bytes("libdemo.so", binary.from_hex(""))', "modes": {"path": "lines"}},
    "parse": {
        "args": {"path": '"demo"'},
        "keys": ["format", "architecture", "type", "interpreter", "needed", "imports", "is_stripped"],
        "nodes": [{"param": "path", "icon": "file", "lines": ["demo", "7f 45 4c 46 (\\x7fELF) \u2026"]},
                  {"arrow": "elf.parse"}, {"result": True, "label": "result \u00b7 everything elf knows (some keys shown)"}],
        "roles": {"path": "a Linux program or .so library"},
    },
    "parse_bytes": {
        "args": {"data": "bin"},
        "keys": ["format", "endian", "type", "entry_hex"],
        "nodes": [{"param": "data", "icon": "cpu", "lines": ["bytes in memory", "7f 45 4c 46 \u2026"]},
                  {"arrow": "elf.parse_bytes"}, {"result": True, "label": "result \u00b7 the same map as parse()"}],
        "roles": {"data": "the file's bytes, already read"},
    },
    "is_elf": {
        "args": {"path": '"demo"'},
        "vary": {"param": "path", "values": ['"demo"', '"notes.txt"'], "labels": ["demo", "notes.txt"]},
        "roles": {"path": "the file to check for the \\x7fELF magic bytes"},
    },
    "sections": {
        "args": {"path": '"demo"'},
        "call": 'elf.sections("demo").filter(s => s.name != "")',
        "keys": ["name", "size", "entropy", "flags"],
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "elf.sections"},
                  {"result": True, "label": "result \u00b7 .text, .rodata, .dynsym ..."}],
        "roles": {"path": "the ELF file"},
    },
    "segments": {
        "args": {"path": '"demo"'},
        "keys": ["type", "flags", "file_size"],
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "elf.segments"},
                  {"result": True, "label": "result \u00b7 what gets loaded, with permissions"}],
        "roles": {"path": "the ELF file"},
    },
    "imports": {
        "args": {"path": '"demo"'},
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "elf.imports"},
                  {"result": True, "label": "result \u00b7 functions it gets from libraries"}],
        "roles": {"path": "the ELF file"},
    },
    "exports": {
        "args": {"path": '"libdemo.so"'},
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "elf.exports"},
                  {"result": True, "label": "result \u00b7 what the library offers"}],
        "vary": {"param": "path", "values": ['"libdemo.so"', '"demo"'], "labels": ["libdemo.so", "demo (none)"]},
        "roles": {"path": "the ELF file (usually a .so)"},
    },
    "needed": {
        "args": {"path": '"demo"'},
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "elf.needed"},
                  {"result": True, "label": "result \u00b7 shared libraries it needs (DT_NEEDED)"}],
        "roles": {"path": "the ELF file"},
    },
    "indicators": {
        "args": {"path_or_info": '"demo"'},
        "keys": ["level", "name"],
        "nodes": [{"param": "path_or_info", "icon": "file", "mode": "lines"},
                  {"box": "checks", "icon": "shield", "lines": ["W+X segments? packed? static?", "network or exec imports?"]},
                  {"arrow": "elf.indicators"}, {"result": True, "label": "result \u00b7 suspicious things, most serious first"}],
        "roles": {"path_or_info": "a file path, or the map elf.parse() gave"},
    },
    "summary": {
        "args": {"path": '"demo"'},
        "mode": "lines",
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "elf.summary"}, {"result": True, "label": "result \u00b7 one line for a report"}],
        "roles": {"path": "the ELF file"},
    },
}
